'use strict';

const { test, describe } = require('node:test');
const assert = require('node:assert/strict');
const request = require('supertest');
const jwt = require('jsonwebtoken');

const { app } = require('./app');

describe('GET /private', () => {
  test('401 with no Authorization header', async () => {
    const res = await request(app).get('/private');
    assert.equal(res.status, 401);
    assert.deepEqual(res.body, { error: 'missing_token' });
  });

  test('401 with garbage token', async () => {
    const res = await request(app)
      .get('/private')
      .set('Authorization', 'Bearer not.a.real.token');
    assert.equal(res.status, 401);
    assert.equal(res.body.error, 'invalid_token');
    assert.notEqual(res.body.error, 'token_expired');
  });

  test('200 with valid token returns sub', async () => {
    const token = jwt.sign({ sub: 'user-42' }, process.env.JWT_SECRET || 'test-secret', {
      algorithm: 'HS256',
      expiresIn: '1h',
    });
    const res = await request(app)
      .get('/private')
      .set('Authorization', `Bearer ${token}`);
    assert.equal(res.status, 200);
    assert.deepEqual(res.body, { sub: 'user-42' });
  });

  test('401 with expired token reports token_expired', async () => {
    const token = jwt.sign({ sub: 'user-42' }, process.env.JWT_SECRET || 'test-secret', {
      algorithm: 'HS256',
      expiresIn: '1ms',
    });
    await new Promise((resolve) => setImmediate(resolve));

    const res = await request(app)
      .get('/private')
      .set('Authorization', `Bearer ${token}`);
    assert.equal(res.status, 401);
    assert.deepEqual(res.body, { error: 'token_expired' });
  });
});

